{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "In normal subjects, pethidine had an absolute oral bioavailability of 50% versus IV, directly demonstrating that a small ionizable drug with first-pass metabolism can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Tolfenamic acid, a chlorinated aromatic carboxylic acid, showed absolute oral bioavailability of 61.6% versus IV in healthy volunteers, supporting high F for the query's halogenated aromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Nifedipine, a lipophilic and poorly water-soluble drug, had absolute oral bioavailability of 42–56% versus IV, indicating that solubility limitations do not preclude F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Saccharin, a sulfonamide-related heterocycle, had a fraction absorbed of 0.84±0.08 versus IV in fasted volunteers, providing direct sulfonamide-class evidence for high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Meclofenamate, a chlorinated fenamate, had human oral bioavailability above 85%, supporting high F for chlorinated aromatic drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with human oral bioavailability data report values well above 20% (pethidine ~50%, tolfenamic acid ~62%, nifedipine 42–56%, saccharin ~84%, meclofenamate >85%). No affirmative low-F evidence transfers to the query. Therefore the query is predicted to have high oral bioavailability (F≥20%).",
  "evidence_gaps": [
    "No query-specific human bioavailability record is present in the provided evidence.",
    "No direct absolute oral bioavailability measurement for a sulfonamide-isoindolinone (chlorthalidone-like) analogue is available; the closest sulfonamide-related evidence is saccharin.",
    "The only sub-20% record (aspirin C33) was not used because it reflects presystemic hydrolysis to salicylate, a mechanism absent in the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

